from __future__ import annotations
import cmath
from dataclasses import dataclass
from typing import Callable

@dataclass(frozen=True)
class RootBracket:
    midpoint: float
    lower: float
    upper: float
    iterations: int

def scalar_log_norm(t: float) -> float:
    return abs(cmath.log(complex(1.0, t)))

def bisect_unit_norm(
    lower: float = 0.5,
    upper: float = 3.0,
    tolerance: float = 1e-12,
) -> RootBracket:
    objective: Callable[[float], float] = lambda t: scalar_log_norm(t) - 1.0
    f_lower = objective(lower)
    f_upper = objective(upper)
    if f_lower * f_upper > 0.0:
        raise ValueError("The endpoints must bracket a crossing.")
    iterations = 0
    while upper - lower > tolerance:
        midpoint = (lower + upper) / 2.0
        f_midpoint = objective(midpoint)
        if f_lower * f_midpoint <= 0.0:
            upper = midpoint
            f_upper = f_midpoint
        else:
            lower = midpoint
            f_lower = f_midpoint
        iterations += 1
    return RootBracket((lower + upper) / 2.0, lower, upper, iterations)

if __name__ == "__main__":
    print(bisect_unit_norm())
